16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "postcode")
66	    private String postcode;
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "household_size")
84	    private Integer householdSize;
85	
86	    @Column(name = "possible_duplicate")
87	    private Boolean possibleDuplicate;
88	
89	    @Column(name = "possible_duplicate_of")
90	    private Integer possibleDuplicateOf;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    public String getTitle() {
96	        return this.title;
97	    }
98	
99	    public void setTitle(String title) {
100	        this.title = title;
101	    }
102	
103	    /**
104	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
105	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
106	     * been supplied.
107	     */
108	    public String getSalutation() {
109	        if (this.title == null || this.title.isEmpty()) {
110	            return this.getLastName();
111	        }
112	        return this.title + " " + this.getLastName();
113	    }
114	
115	    public String getAddress() {
116	        return this.address;
117	    }
118	
119	    public void setAddress(String address) {
120	        this.address = address;
121	    }
122	
123	    public String getAddressLine1() {
124	        return this.addressLine1;
125	    }
126	
127	    public void setAddressLine1(String addressLine1) {
128	        this.addressLine1 = addressLine1;
129	    }
130	
131	    public String getAddressLine2() {
132	        return this.addressLine2;
133	    }
134	
135	    public void setAddressLine2(String addressLine2) {
136	        this.addressLine2 = addressLine2;
137	    }
138	
139	    public String getCity() {
140	        return this.city;
141	    }
142	
143	    public void setCity(String city) {
144	        this.city = city;
145	    }
146	
147	    public String getTelephone() {
148	        return this.telephone;
149	    }
150	
151	    public void setTelephone(String telephone) {
152	        this.telephone = telephone;
153	    }
154	
155	    /**
156	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
157	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
158	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
159	     * been set.
160	     */
161	    public String getTelephoneDisplay() {
162	        return Telephone.forDisplay(this.telephone);
163	    }
164	
165	    public String getEmail() {
166	        return this.email;
167	    }
168	
169	    public void setEmail(String email) {
170	        this.email = email;
171	    }
172	
173	    public String getPostcode() {
174	        return this.postcode;
175	    }
176	
177	    public void setPostcode(String postcode) {
178	        this.postcode = postcode;
179	    }
180	
181	    public LocalDate getRegistrationDate() {
182	        return this.registrationDate;
183	    }
184	
185	    public void setRegistrationDate(LocalDate registrationDate) {
186	        this.registrationDate = registrationDate;
187	    }
188	
189	    public LocalDate getBirthDate() {
190	        return this.birthDate;
191	    }
192	
193	    public void setBirthDate(LocalDate birthDate) {
194	        this.birthDate = birthDate;
195	    }
196	
197	    public String getCustomerCode() {
198	        return this.customerCode;
199	    }
200	
201	    public void setCustomerCode(String customerCode) {
202	        this.customerCode = customerCode;
203	    }
204	
205	    public String getHouseholdId() {
206	        return this.householdId;
207	    }
208	
209	    public void setHouseholdId(String householdId) {
210	        this.householdId = householdId;
211	    }
212	
213	    public Integer getNamesakeCount() {
214	        return this.namesakeCount;
215	    }
216	
217	    public void setNamesakeCount(Integer namesakeCount) {
218	        this.namesakeCount = namesakeCount;
219	    }
220	
221	    public Integer getHouseholdSize() {
222	        return this.householdSize;
223	    }
224	
225	    public void setHouseholdSize(Integer householdSize) {
226	        this.householdSize = householdSize;
227	    }
228	
229	    /**
230	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
231	     * postcode while holding a different telephone. Resolved at creation and stored so it is
232	     * reported consistently on every later read.
233	     */
234	    public Boolean getPossibleDuplicate() {
235	        return this.possibleDuplicate;
236	    }
237	
238	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
239	        this.possibleDuplicate = possibleDuplicate;
240	    }
241	
242	    /**
243	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
244	     * is not a possible duplicate.
245	     */
246	    public Integer getPossibleDuplicateOf() {
247	        return this.possibleDuplicateOf;
248	    }
249	
250	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
251	        this.possibleDuplicateOf = possibleDuplicateOf;
252	    }
253	
254	    /**
255	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
256	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
257	     * email or household contributes an empty string. Two owners are duplicates only when their
258	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
259	     * different telephones have distinct identity keys and are both allowed.
260	     */
261	    public String getIdentityKey() {
262	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
263	    }
264	
265	    private static String orEmpty(String value) {
266	        return value == null ? "" : value;
267	    }
268	
269	    /**
270	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
271	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
272	     * from the owner's own fields; absent until both the customer code and registration date
273	     * have been assigned.
274	     */
275	    public String getMembershipNumber() {
276	        if (this.customerCode == null || this.registrationDate == null) {
277	            return null;
278	        }
279	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
280	    }
281	
282	    /**
283	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
284	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
285	     */
286	    public Integer getCheckDigit() {
287	        if (this.customerCode == null) {
288	            return null;
289	        }
290	        return Luhn.checkDigit(this.customerCode);
291	    }
292	
293	    /**
294	     * The owner's tenure in whole days: the number of days elapsed from the
295	     * {@link #getRegistrationDate() registration date} up to today. A freshly registered owner has
296	     * a tenure of zero. Absent until a registration date is present.
297	     */
298	    public Long getTenureDays() {
299	        if (this.registrationDate == null) {
300	            return null;
301	        }
302	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
303	    }
304	
305	    /**
306	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
307	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
308	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
309	     * points once the owner's {@link #getTenureDays() tenure} exceeds 365 days.
310	     */
311	    public Integer getMembershipPoints() {
312	        int points = 0;
313	        boolean hasEmail = this.email != null && !this.email.isEmpty();
314	        if (hasEmail) {
315	            points += 2;
316	        }
317	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
318	        if (unique) {
319	            points += 1;
320	        }
321	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
322	        if (sharedHousehold) {
323	            points += 2;
324	        }
325	        Long tenureDays = getTenureDays();
326	        boolean tenured = tenureDays != null && tenureDays > 365;
327	        if (tenured) {
328	            points += 3;
329	        }
330	        return points;
331	    }
332	
333	    /**
334	     * The owner's membership level, a number from 1 to 4 derived from the owner's
335	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
336	     * 4 for 6 or more.
337	     */
338	    public Integer getMembershipLevel() {
339	        int points = getMembershipPoints();
340	        if (points >= 6) {
341	            return 4;
342	        }
343	        if (points >= 4) {
344	            return 3;
345	        }
346	        if (points >= 2) {
347	            return 2;
348	        }
349	        return 1;
350	    }
351	
352	    /**
353	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
354	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
355	     * before a customer code has been assigned.
356	     */
357	    public String getLocality() {
358	        if (this.customerCode == null) {
359	            return Regions.UNKNOWN;
360	        }
361	        int separator = this.customerCode.indexOf('-');
362	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
363	    }
364	
365	    /**
366	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
367	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
368	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
369	     */
370	    public String getTimezone() {
371	        return Regions.timezoneOf(getLocality());
372	    }
373	
374	    /**
375	     * The owner's preferred contact channel, derived from the owner's own fields:
376	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
377	     */
378	    public String getContactPreference() {
379	        boolean hasEmail = this.email != null && !this.email.isEmpty();
380	        return hasEmail ? "EMAIL" : "PHONE";
381	    }
382	
383	    /**
384	     * The owner's age band, derived from the owner's own fields: the whole years between
385	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
386	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
387	     * (65 or older). Absent until a birth date and a registration date are both present.
388	     */
389	    public String getAgeBand() {
390	        if (this.birthDate == null || this.registrationDate == null) {
391	            return null;
392	        }
393	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
394	        if (age < 18) {
395	            return "MINOR";
396	        }
397	        return age < 65 ? "ADULT" : "SENIOR";
398	    }
399	
400	    /**
401	     * Resolve the effective registration date before persisting: default it to the server's
402	     * current date when none was supplied, then roll it forward off weekends so a newly
403	     * registered owner always has a business-day registration date. Every value derived from it
404	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
405	     * date.
406	     */
407	    @PrePersist
408	    private void resolveRegistrationDate() {
409	        if (this.registrationDate == null) {
410	            this.registrationDate = LocalDate.now();
411	        }
412	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
413	    }
414	
415	    protected Set<Pet> getPetsInternal() {
416	        if (this.pets == null) {
417	            this.pets = new HashSet<>();
418	        }
419	        return this.pets;
420	    }
421	
422	    protected void setPetsInternal(Set<Pet> pets) {
423	        this.pets = pets;
424	    }
425	
426	    public List<Pet> getPets() {
427	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
428	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
429	        return Collections.unmodifiableList(sortedPets);
430	    }
431	
432	    public void setPets(List<Pet> pets) {
433	        this.pets = new HashSet<>(pets);
434	    }
435	
436	    public void addPet(Pet pet) {
437	        getPetsInternal().add(pet);
438	        pet.setOwner(this);
439	    }
440	
441	    /**
442	     * Return the Pet with the given name, or null if none found for this Owner.
443	     *
444	     * @param name to test
445	     * @return true if pet name is already in use
446	     */
447	    public Pet getPet(String name) {
448	        return getPet(name, false);
449	    }
450	
451	    /**
452	     * Return the Pet with the given name, or null if none found for this Owner.
453	     *
454	     * @param name to test
455	     * @return true if pet name is already in use
456	     */
457	    public Pet getPet(String name, boolean ignoreNew) {
458	        name = name.toLowerCase();
459	        for (Pet pet : getPetsInternal()) {
460	            if (!ignoreNew || !pet.isNew()) {
461	                String compName = pet.getName();
462	                compName = compName.toLowerCase();
463	                if (compName.equals(name)) {
464	                    return pet;
465	                }
466	            }
467	        }
468	        return null;
469	    }
470	
471	    public Pet getPet(Integer petId) {
472	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
473	    }
474	
475	    @Override
476	    public String toString() {
477	        return new ToStringCreator(this)
478	
479	            .append("id", this.getId())
480	            .append("new", this.isNew())
481	            .append("lastName", this.getLastName())
482	            .append("firstName", this.getFirstName())
483	            .append("address", this.address)
484	            .append("city", this.city)
485	            .append("telephone", this.telephone)
486	            .append("email", this.email)
487	            .toString();
488	    }
489	}
